select coalesce(json_agg(json_build_object('name',c.relname,'kind',c.relkind,'rls_enabled',c.relrowsecurity,'rls_forced',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner)) order by c.relname),'[]'::json) as data from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p','v','m','f','S');
